namespace sv_3e9aa8422ae349288bda9d56187df1b4.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, "Scoped" = one instance per circuit (user connection).
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#6366f1";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Components subscribe to this to re-render when theme state changes.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island rendered inside the static layout *@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@* Interactive island usable in the sidebar or anywhere in the static layout *@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<button class="theme-toggle" @onclick="CycleTheme"
        style="border-color: @ThemeService.AccentColor;">
    @GetIcon() Toggle Theme
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            Services.ThemeMode.Light => Services.ThemeMode.Dark,
            Services.ThemeMode.Dark => Services.ThemeMode.System,
            _ => Services.ThemeMode.Light
        };
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<PageTitle>User Preferences</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <h3>Theme</h3>
    <div class="theme-options">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <label>
                <input type="radio" name="theme"
                       checked="@(ThemeService.Theme == mode)"
                       @onchange="() => ThemeService.Theme = mode" />
                @mode
            </label>
        }
    </div>

    <h3>Accent Color</h3>
    <input type="color" value="@ThemeService.AccentColor"
           @onchange="HandleColorChange" />
    <span style="color: @ThemeService.AccentColor;">Preview</span>

    <p class="current-state">
        Current: <strong>@ThemeService.Theme</strong> / @ThemeService.AccentColor
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleColorChange(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#6366f1";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

